  private async ensureVerifierApproved(command: string, confirmHandler?: ConfirmHandler): Promise<boolean> {
    const isTrusted = isWorkspaceTrusted(this.config.workspace, this.isReadOnly());
    const mode = this.getApprovalMode();
    const policyContext: PolicyContext = {
      mode,
      trusted: isTrusted,
      sandbox: this.config.sandbox,
      approvedEgressOrigins: this.approvedEgressOrigins,
      fullAccess: Boolean(this.config.fullAccess) && !this.isReadOnly(),
    };

    if (!this.approvalPolicy.requiresDecision("exec", policyContext)) {
      return true;
    }

    const desc = describeVerifier(this.config.workspace, command);
    const verifierCmd = desc?.command || command;
    const digest = desc?.digest || createHash("sha256").update(verifierCmd).digest("hex");
    const cacheKey = `${this.config.workspace}:${verifierCmd}:${digest}`;

    if (this.approvedVerifiers.has(cacheKey)) {
      return true;
    }

    const onConfirm = confirmHandler ?? this.activeTurn?.onConfirm;
    if (!onConfirm) {
      return false;
    }

    const approved = await onConfirm("verifier", {
      command: verifierCmd,
      script: desc?.script,
      detail: desc?.evidence,
      digest,
    });

    if (approved) {
      this.approvedVerifiers.add(cacheKey);
      return true;
    }
    return false;
  }

  /**
   * Before the first tool that may mutate an unverified change, capture the verifier definition, operator-declared
   * scope and test files. A discovered verifier also runs before the tool so independence can be judged
   * fail-before/pass-after. A configured verifier is an operator check and needs its immutable binding snapshot, but
   * does not run before a change.
  private verifierState(): { inputs: string; epoch: string; mutationSeq: number; external: string } | undefined {
    try {
      const inputs = this.candidateTracker.computeCandidateIdentitySync(this.config.workspace).candidateId;
      return { inputs, epoch: this.epoch, mutationSeq: this.mutationSeq, external: externalInputsFingerprint(this.config.workspace) };
    } catch {
      return undefined;
    }
  }

    this.spine.registerHandler("enable_tools", async (args) => {
      const asked: unknown[] = Array.isArray(args?.groups) ? args.groups : [];
      const known = asked.filter((g): g is string => typeof g === "string" && g in TOOL_GROUPS);
      if (!known.length) return { success: false, output: "", error: `enable_tools: name one or more of: ${Object.keys(TOOL_GROUPS).join(", ")}.` };
      for (const group of known) this.enabledToolGroups.add(group);
      return { success: true, output: `Enabled ${known.join(", ")}: ${known.flatMap((g) => TOOL_GROUPS[g].tools).join(", ")} available from your next step.` };
    });

    this.spine.registerHandler("read_archive", async (args) => {
      const result = readArchive(this.archiveForReading, args ?? {});
      return result.ok ? { success: true, output: result.text } : { success: false, output: "", error: result.text };
    });

    this.spine.registerHandler("read_findings", async (args) => {
      const result = readFindings(this.findingNotes, args ?? {});
      return result.ok ? { success: true, output: result.text } : { success: false, output: "", error: result.text };
    });

    this.spine.registerHandler("update_requirements", async (args) => {
      if (!this.objective) {
        return { success: false, output: "", error: "No operator objective is being tracked in this conversation." };
      }
      const updates: RequirementUpdate[] = Array.isArray(args?.requirements) ? args.requirements : [];
      const wantsVerified = updates.some((u) => u?.status === "verified");
      const ledger = this.objective;
      if (wantsVerified) {
        const claimed = updates.flatMap((u) => ledger.requirements.filter((r) => u?.status === "verified" && r.id === u.id && isHardRequirement(r) && r.verifier));
        for (const r of claimed) await this.runRequirementVerifier(r.id, r.verifier!);
      }
      const state = wantsVerified ? this.verifierState() : undefined;
      if (!text) {
        errors.push(`${update.id ?? "(no id)"}: unknown requirement; to add one, give its text`);
        continue;
      }
      requirement = {
        id: `M${ledger.requirements.filter((r) => r.source === "model").length + 1}`,
        text: clip(text, MAX_REQUIREMENT_TEXT),
        status: "open",
        source: "model",
        evidence: [],
        updatedAt: at,
      };
      ledger.requirements.push(requirement);
      changed = true;
    } else if (update.text && update.text.trim() !== requirement.text && requirement.source !== "model") {
      errors.push(`${requirement.id}: the operator's requirement text cannot be changed`);
    }
    if (update.kind !== undefined && update.kind !== (requirement.kind ?? "feature")) {
      if (!REQUIREMENT_KINDS.includes(update.kind)) errors.push(`${requirement.id}: unknown kind ${String(update.kind)}`);
      else if (requirement.source !== "model") errors.push(`${requirement.id}: the operator's requirement type cannot be changed`);
      else {
        requirement.kind = update.kind;
        changed = true;
      }
    }
    const verifier = typeof update.verifier === "string" ? cleanLine(update.verifier, MAX_VERIFIER_CHARS) : "";
    if (verifier && verifier !== requirement.verifier) {
      if (!isHardRequirement(requirement)) errors.push(`${requirement.id}: a verifier applies to a constraint or invariant`);
      else if (requirement.source !== "model" || requirement.verifier) errors.push(`${requirement.id}: its verifier is fixed and cannot be changed`);
      else {
        requirement.verifier = verifier;
        changed = true;
      }
    }
    for (const link of Array.isArray(update.tests) ? update.tests : update.tests ? [update.tests] : []) {
      const test = typeof link === "string" ? cleanLine(link, MAX_TEST_LINK_CHARS) : "";
      if (test && !(requirement.tests ?? []).includes(test)) {
        requirement.tests = [...(requirement.tests ?? []), test].slice(-MAX_TEST_LINKS);
        changed = true;
      }
    }
    if (status && status !== requirement.status) {
      if ((status === "descoped" || status === "blocked") && !note) {
        errors.push(`${requirement.id}: ${status} needs a note giving the reason`);
        continue;
      }
      if ((status === "implemented" || status === "verified") && evidence.length === 0 && requirement.evidence.length === 0) {
        errors.push(`${requirement.id}: ${status} needs evidence (files changed, commands run, tests passed)`);
        continue;
      }
      // `verified` is not the model's word: it binds a passing verifier run recorded on the current workspace.
        changed = true;
      }
    }
    if (requirement.evidence.length > MAX_EVIDENCE_ITEMS) requirement.evidence = requirement.evidence.slice(-MAX_EVIDENCE_ITEMS);
    requirement.updatedAt = at;
  }
  if (typeof nextAction === "string" && nextAction.trim() && nextAction.trim() !== ledger.nextAction) {
    ledger.nextAction = clip(nextAction.trim(), MAX_EVIDENCE_CHARS);
    changed = true;
  }
  return { ok: errors.length === 0, changed, errors };
}

export function queueSteering(ledger: ObjectiveLedger, id: string, text: string, at = now()): SteeringRecord | undefined {
  if (ledger.steering.some((s) => s.id === id)) return undefined;
  const record: SteeringRecord = { id, text, receivedAt: at, status: "queued" };
  ledger.steering.push(record);
  return record;
}

/**
 * After any change to the workspace, verified requirements rest on a verifier run of an older state: they become
 * implemented (model-reported) again, with a note. Returns the ids demoted.
 */
export function invalidateVerified(ledger: ObjectiveLedger, reason: string, at = now()): string[] {
  const demoted: string[] = [];
  for (const r of ledger.requirements) {
    if (r.status !== "verified") continue;
    r.status = "implemented";
    r.note = clip(`verification invalidated: ${reason}${r.verifiedBy ? ` (was verifier #${r.verifiedBy.attempt})` : ""}`, MAX_EVIDENCE_CHARS);
    r.verifiedBy = undefined;
    r.updatedAt = at;
    demoted.push(r.id);
  }
  return demoted;
}

/** The first line of a failing verifier's output that names the failure; else its last non-empty line. */
export function failedCheckFrom(output: string): string | undefined {
  const lines = output.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  // Lines that report a failure first (an echoed command that merely mentions "FAIL" is not one), then any mention.
  const reported = lines.find((line) => /^(✖|×|not ok\b|FAIL(ED)?\b|error(\[|:|\b)|thread .* panicked|test result: FAILED|AssertionError)/i.test(line));
  const failing = reported ?? lines.find((line) => /(\bFAIL(ED)?\b|\bfailed\b|\berror\[|panicked)/i.test(line) && !/\b0 failed\b/.test(line));
  const chosen = failing ?? lines[lines.length - 1];
  return chosen ? clip(chosen, MAX_EVIDENCE_CHARS) : undefined;
}

